import React, { useEffect, useState } from "react";
import axios from "axios";

export default function PaymentNumber({ token }) {
  const [bkash, setBkash] = useState("");
  const [nagad, setNagad] = useState("");

  // Load payment numbers on component mount
  useEffect(() => {
    axios
      .get("http://localhost:8080/api/payment-config", {
        headers: { Authorization: `Bearer ${token}` }
      })
      .then((res) => {
        const data = res.data;
        const bkashConfig = data.find((c) => c.method === "bKash");
        const nagadConfig = data.find((c) => c.method === "Nagad");

        if (bkashConfig) setBkash(bkashConfig.number);
        if (nagadConfig) setNagad(nagadConfig.number);
      })
      .catch((err) => console.error("Error loading payment configs:", err));
  }, [token]);

  // Save payment number to backend
  const saveNumber = (method, number) => {
    axios
      .post(
        "http://localhost:8080/api/payment-config",
        null,
        {
          params: { method, number },
          headers: { Authorization: `Bearer ${token}` }
        }
      )
      .then(() => alert(`${method} number updated successfully`))
      .catch((err) => console.error("Error saving payment number:", err));
  };

  return (
    <div style={{ padding: "20px", maxWidth: "500px", margin: "auto" }}>
      <h2 style={{ textAlign: "center" }}>Payment Number Settings</h2>

      {/* বিকাশ */}
      <div style={{
        border: "1px solid #ccc",
        padding: "15px",
        borderRadius: "5px",
        marginBottom: "20px",
        backgroundColor: "#f9f9f9"
      }}>
        <h3 style={{ marginBottom: "10px", color: "#d81b60" }}>বিকাশ নাম্বার</h3>
        <input
          type="text"
          value={bkash}
          placeholder="Enter bKash Number"
          onChange={(e) => setBkash(e.target.value)}
          style={{
            width: "100%",
            padding: "8px",
            border: "1px solid #ccc",
            borderRadius: "4px",
            marginBottom: "8px"
          }}
        />
        <button
          onClick={() => saveNumber("bKash", bkash)}
          style={{
            backgroundColor: "#d81b60",
            color: "white",
            padding: "8px 15px",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer"
          }}
        >
          Save bKash
        </button>
      </div>

      {/* নগদ */}
      <div style={{
        border: "1px solid #ccc",
        padding: "15px",
        borderRadius: "5px",
        backgroundColor: "#f9f9f9"
      }}>
        <h3 style={{ marginBottom: "10px", color: "#ff6f00" }}>নগদ নাম্বার</h3>
        <input
          type="text"
          value={nagad}
          placeholder="Enter Nagad Number"
          onChange={(e) => setNagad(e.target.value)}
          style={{
            width: "100%",
            padding: "8px",
            border: "1px solid #ccc",
            borderRadius: "4px",
            marginBottom: "8px"
          }}
        />
        <button
          onClick={() => saveNumber("Nagad", nagad)}
          style={{
            backgroundColor: "#ff6f00",
            color: "white",
            padding: "8px 15px",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer"
          }}
        >
          Save Nagad
        </button>
      </div>
    </div>
  );
}
